import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Navigate, useNavigate, Link } from 'react-router-dom';
import { 
  UserIcon, 
  MapPinIcon, 
  PhoneIcon, 
  EnvelopeIcon, 
  CameraIcon,
  ArrowLeftOnRectangleIcon,
  CheckCircleIcon,
  XCircleIcon
} from '@heroicons/react/24/outline';
import axios from 'axios';

const Profile = () => {
  const { user, token, setUser, logout } = useAuth();
  const navigate = useNavigate();

  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showLogoutModal, setShowLogoutModal] = useState(false);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    if (user && token) {
      loadUserProfile();
      loadUserOrders();
    } else {
      setLoading(false);
    }
  }, [token, user?.id]);

  const loadUserProfile = async () => {
    try {
      const response = await axios.get('http://localhost:3000/api/users/profile', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const userData = response.data.user;
      setUser(userData);
      localStorage.setItem('farm2home_user', JSON.stringify(userData));
      if (userData.profilePhoto) {
        setPhotoPreview(`http://localhost:3000${userData.profilePhoto}`);
      }
    } catch (error) {
      console.error('Error loading profile:', error);
      if (error.response?.status === 401) logout();
    } finally {
      setLoading(false);
    }
  };

  const loadUserOrders = async () => {
    try {
      const response = await axios.get(`http://localhost:3000/api/orders/customer/${user._id}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      setOrders(response.data.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)));
    } catch (error) {
      console.error('Error loading user orders:', error);
      setOrders([]);
    }
  };

  const updateOrderStatus = (orderId, newStatus) => {
    const allOrders = JSON.parse(localStorage.getItem('farm2home_orders') || '[]');
    const updatedOrders = allOrders.map(order => 
      order.id === orderId ? { ...order, status: newStatus } : order
    );
    localStorage.setItem('farm2home_orders', JSON.stringify(updatedOrders));
    loadUserOrders(); // Refresh local list
    alert(`Order ${newStatus}!`);
  };

  const confirmLogout = () => {
    logout(); 
    setShowLogoutModal(false);
    navigate('/', { replace: true });
  };

  const handlePhotoChange = async (event) => {
    const file = event.target.files[0];
    if (!file) return;
    setUploading(true);
    const formData = new FormData();
    formData.append('profilePhoto', file);
    try {
      const response = await axios.post('http://localhost:3000/api/users/upload-photo', formData, {
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'multipart/form-data' }
      });
      const updatedUser = { ...user, profilePhoto: response.data.photoUrl };
      setUser(updatedUser);
      setPhotoPreview(`http://localhost:3000${response.data.photoUrl}`);
      alert('Photo updated!');
    } catch (error) {
      alert('Upload failed');
    } finally {
      setUploading(false);
    }
  };

  if (!user && !loading) return <Navigate to="/login" />;

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto"></div>
          <p className="mt-4 text-gray-600 font-medium">Loading your profile...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-10">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Profile Header Card */}
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 mb-8">
          <div className="flex flex-col md:flex-row items-center md:items-start space-y-4 md:space-y-0 md:space-x-8">
            <div className="relative">
              <div className="w-28 h-28 bg-green-100 rounded-full flex items-center justify-center overflow-hidden border-4 border-white shadow-md">
                {uploading ? (
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-green-600"></div>
                ) : photoPreview ? (
                  <img src={photoPreview} alt="Profile" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-3xl font-bold text-green-700">{user?.name?.charAt(0).toUpperCase()}</span>
                )}
              </div>
              <label className="absolute bottom-1 right-1 bg-green-600 hover:bg-green-700 text-white p-2 rounded-full cursor-pointer shadow-lg transition-all transform hover:scale-110">
                <CameraIcon className="w-4 h-4" />
                <input type="file" accept="image/*" onChange={handlePhotoChange} className="hidden" disabled={uploading} />
              </label>
            </div>

            <div className="flex-1 text-center md:text-left">
              <h1 className="text-3xl font-extrabold text-gray-900">{user?.name}</h1>
              <p className="text-green-600 font-medium capitalize mb-4">{user?.userType}</p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm text-gray-600">
                <div className="flex items-center justify-center md:justify-start">
                  <EnvelopeIcon className="w-4 h-4 mr-2 text-gray-400" /> {user?.email}
                </div>
                <div className="flex items-center justify-center md:justify-start">
                  <PhoneIcon className="w-4 h-4 mr-2 text-gray-400" /> {user?.phone}
                </div>
                <div className="flex items-center justify-center md:justify-start sm:col-span-2">
                  <MapPinIcon className="w-4 h-4 mr-2 text-gray-400" /> {user?.address}
                </div>
              </div>
            </div>

            <button onClick={() => setShowLogoutModal(true)} className="flex items-center text-red-600 hover:bg-red-50 px-4 py-2 rounded-lg transition-colors text-sm font-semibold border border-transparent hover:border-red-100">
              <ArrowLeftOnRectangleIcon className="w-5 h-5 mr-2" /> Logout
            </button>
          </div>
        </div>

        {/* Order History / Requests */}
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
          <div className="px-8 py-5 border-b border-gray-100 flex justify-between items-center">
            <h2 className="text-xl font-bold text-gray-800">
              {user?.userType === 'farmer' ? 'Customer Requests' : 'Order History'}
            </h2>
          </div>

          <div className="max-h-[600px] overflow-y-auto">
            {orders.length === 0 ? (
              <div className="text-center py-20 text-gray-500">
                <p className="italic">No orders found.</p>
              </div>
            ) : (
              <div className="divide-y divide-gray-50">
                {orders.map(order => (
                  <div key={order.id} className="p-8 hover:bg-gray-50 transition-colors">
                    <div className="flex justify-between items-start mb-4">
                      <div>
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="font-bold text-gray-900">Order #{order.id.toString().slice(-6)}</h3>
                          <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase ${
                            order.status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                            order.status === 'confirmed' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                          }`}>
                            {order.status}
                          </span>
                        </div>
                        <p className="text-xs text-gray-400">{new Date(order.createdAt).toLocaleString()}</p>
                        {user?.userType === 'farmer' && (
                           <p className="text-sm text-green-700 font-medium mt-1">From: {order.customerName}</p>
                        )}
                      </div>

                      {/* FARMER ACTIONS */}
                      {user?.userType === 'farmer' && order.status === 'pending' && (
                        <div className="flex gap-2">
                          <button 
                            onClick={() => updateOrderStatus(order.id, 'confirmed')}
                            className="p-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors shadow-sm"
                            title="Confirm Order"
                          >
                            <CheckCircleIcon className="w-5 h-5" />
                          </button>
                          <button 
                            onClick={() => updateOrderStatus(order.id, 'cancelled')}
                            className="p-2 bg-red-100 text-red-600 rounded-lg hover:bg-red-200 transition-colors shadow-sm"
                            title="Reject Order"
                          >
                            <XCircleIcon className="w-5 h-5" />
                          </button>
                        </div>
                      )}

                      <span className="bg-gray-100 text-gray-800 px-3 py-1 rounded-full text-xs font-bold">
                        ₹{order.total}
                      </span>
                    </div>

                    <div className="space-y-2">
                      {order.items.map((item, i) => (
                        <div key={i} className="flex justify-between text-sm text-gray-600">
                          <span>{item.name} <span className="text-gray-400">x{item.quantity}</span></span>
                          <span className="font-medium text-gray-800">₹{item.price * item.quantity}</span>
                        </div>
                      ))}
                    </div>

                    {user?.userType === 'farmer' && (
                       <div className="mt-4 pt-3 border-t border-dashed text-xs text-gray-500">
                          <strong>Delivery Address:</strong> {order.customerAddress}
                       </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Logout Confirmation Modal */}
      {showLogoutModal && (
        <div className="fixed inset-0 flex items-center justify-center z-[100]">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowLogoutModal(false)}></div>
          <div className="bg-white rounded-2xl p-8 w-full max-w-sm text-center relative z-10 shadow-2xl">
            <h2 className="text-xl font-bold mb-4">Logout?</h2>
            <div className="flex space-x-3">
              <button onClick={() => setShowLogoutModal(false)} className="flex-1 px-4 py-3 bg-gray-100 rounded-xl">Cancel</button>
              <button onClick={confirmLogout} className="flex-1 px-4 py-3 bg-red-600 text-white rounded-xl">Logout</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Profile;
